/*!50003 CREATE*/ /*!50017 DEFINER=`oliver.sanchez`@`%`*/ /*!50003 TRIGGER `trg_tb_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (
        `table_name`, `table_operation`, `db_user`, 
        `operation_date`, `operation_description`, `operation_status`
    ) VALUES (
        'tb_people', 
        'Create', 
        USER(), 
        NOW(), 
        CONCAT(
            'Persona registrada | ID: ', NEW.person_ID, 
            ' | Nombre: ', COALESCE(NEW.courtesy_title, ''), ' ', NEW.given_names, ' ', NEW.family_names,
            ' | user_ID: ', COALESCE(NEW.user_ID, 'Sin usuario'),
            ' | Género: ', NEW.gender,
            ' | Teléfono: ', COALESCE(NEW.phone, 'N/A')
        ), 
        b'1'
    );
