/*!50003 CREATE*/ /*!50017 DEFINER=`oliver.sanchez`@`%`*/ /*!50003 TRIGGER `trg_tb_people_after_update` AFTER UPDATE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (
        `table_name`, `table_operation`, `db_user`, 
        `operation_date`, `operation_description`, `operation_status`
    ) VALUES (
        'tb_people', 
        'Update', 
        USER(), 
        NOW(), 
        CONCAT(
            'Persona modificada | ID: ', NEW.person_ID,
            ' | Nombre anterior: ', OLD.given_names, ' ', OLD.family_names,
            ' -> Nuevo nombre: ', NEW.given_names, ' ', NEW.family_names,
            ' | Teléfono: ', COALESCE(OLD.phone, 'N/A'), ' -> ', COALESCE(NEW.phone, 'N/A'),
            ' | Estado: ', IF(OLD.status = b'1', 'Activo', 'Inactivo'), ' -> ', IF(NEW.status = b'1', 'Activo', 'Inactivo')
        ), 
        b'1'
    );
END */;;
