/*!50003 CREATE*/ /*!50017 DEFINER=`oliver.sanchez`@`%`*/ /*!50003 TRIGGER `trg_products_after_insert` AFTER INSERT ON `tb_products` FOR EACH ROW BEGIN
    INSERT INTO tb_logs
    (
        table_name,
        table_operation,
        db_user,
        operation_description,
        operation_date
    )
    VALUES
    (
        'tb_products',
        'Create',
        USER(),
        CONCAT(
            'Producto creado ID=',
            NEW.ID,
            ', SKU=',
            NEW.SKU,
            ', Nombre=',
            NEW.name
        ),
        NOW()
    );
END */;;
DELIMITER ;
