/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tbc_categories_after_update` AFTER UPDATE ON `tbc_categories` FOR EACH ROW BEGIN
    DECLARE cambios TEXT DEFAULT '';

    IF NOT (OLD.name <=> NEW.name) THEN
        SET cambios = CONCAT(
            cambios,
            'Nombre: "', OLD.name,
            '" -> "', NEW.name, '". '
        );
    END IF;

    IF NOT (OLD.description <=> NEW.description) THEN
        SET cambios = CONCAT(
            cambios,
            'Descripción: "',
            COALESCE(OLD.description, 'Sin descripción'),
            '" -> "',
            COALESCE(NEW.description, 'Sin descripción'),
            '". '
        );
    END IF;

    IF NOT (OLD.sup_id_category <=> NEW.sup_id_category) THEN
        SET cambios = CONCAT(
            cambios,
            'Categoría superior: ',
            COALESCE(OLD.sup_id_category, 'Sin categoría superior'),
            ' -> ',
            COALESCE(NEW.sup_id_category, 'Sin categoría superior'),
            '. '
        );
    END IF;

    IF NOT (OLD.status <=> NEW.status) THEN
        SET cambios = CONCAT(
            cambios,
            'Estado: ',
            COALESCE(OLD.status, 0),
            ' -> ',
            COALESCE(NEW.status, 0),
            '. '
        );
    END IF;

    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_description
    )
    VALUES (
        'tbc_categories',
        'Update',
        USER(),
        CONCAT(
            'Categoría actualizada. ID: ',
            NEW.ID,
            '. Cambios: ',
            cambios
        )
    );
END */;;
DELIMITER ;
