CREATE DEFINER=`oliver.sanchez`@`%` FUNCTION `fn_p03_activo`(p_num INT, p_porcentaje INT) RETURNS tinyint
    NO SQL
    DETERMINISTIC
BEGIN
  IF p_porcentaje < 0 OR p_porcentaje > 100 THEN
    RETURN NULL;
  END IF;
  -- Para 5,000 numeros consecutivos y 80%, genera exactamente 4,000 activos.
  RETURN IF(MOD(ABS(p_num * 37 + 11), 100) < p_porcentaje, 1, 0);
END ;;
DELIMITER ;
