CREATE DEFINER=`oliver.sanchez`@`%` FUNCTION `fn_p03_genero`(p_num INT) RETURNS varchar(20) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
  RETURN CASE MOD(ABS(p_num), 3)
