CREATE DEFINER=`oliver.sanchez`@`%` FUNCTION `fn_p03_nacimiento`(p_num INT, p_edad_min INT, p_edad_max INT) RETURNS date
    NO SQL
BEGIN
  DECLARE v_edad INT;
  IF p_edad_min < 0 OR p_edad_max < p_edad_min OR p_edad_max > 110 THEN
    RETURN NULL;
  END IF;
  SET v_edad = p_edad_min + MOD(ABS(p_num), p_edad_max - p_edad_min + 1);
  -- Restar dias hace que la edad cumplida quede siempre en el rango pedido.
  RETURN DATE_SUB(DATE_SUB(CURDATE(), INTERVAL v_edad YEAR), INTERVAL MOD(ABS(p_num * 13), 300) DAY);
END ;;
DELIMITER ;
