CREATE DEFINER=`oliver.sanchez`@`%` FUNCTION `fn_p03_nombre`(p_num INT, p_genero VARCHAR(20)) RETURNS varchar(150) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
  IF p_genero = 'Hombre' THEN
    RETURN ELT(MOD(ABS(p_num), 12) + 1,
      'Alejandro','Daniel','Javier','Miguel','Luis','Carlos',
      'Andrés','Mateo','Fernando','Diego','José','Santiago');
  ELSEIF p_genero = 'Mujer' THEN
    RETURN ELT(MOD(ABS(p_num), 12) + 1,
      'Sofía','Valeria','Daniela','Camila','Mariana','Lucía',
      'Ana','Elena','Isabella','Paola','Renata','Gabriela');
  END IF;
  RETURN ELT(MOD(ABS(p_num), 12) + 1,
    'Alex','Sam','Ariel','Emilio','Andrea','Noel',
    'Mar','Ángel','Gael','Dani','Cris','Robin');
END ;;
DELIMITER ;
