DELIMITER ;;
CREATE DEFINER=`oliver.sanchez`@`%` PROCEDURE `sp_p03_simular_usuarios`(
    IN p_escenario TINYINT,
    IN p_cantidad INT
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_i INT DEFAULT 1;
    DECLARE v_id INT;
    DECLARE v_genero VARCHAR(20);
    DECLARE v_pais CHAR(2);
    DECLARE v_estado TINYINT;
    DECLARE v_correo VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_nombre VARCHAR(150);
    DECLARE v_apellidos VARCHAR(150);
    DECLARE v_nacimiento DATE;
    DECLARE v_ya_existen INT DEFAULT 0;

    -- Si falla cualquier INSERT, deshacer ambos registros y los logs asociados.
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_escenario NOT IN (1, 2, 3) OR p_escenario IS NULL
       OR p_cantidad IS NULL
       OR (p_escenario = 1 AND p_cantidad <> 500)
       OR (p_escenario = 2 AND p_cantidad <> 2000)
       OR (p_escenario = 3 AND p_cantidad <> 5000) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Parametros invalidos: usar (1,500), (2,2000) o (3,5000)';
    END IF;

    -- Evitar una segunda ejecucion del mismo escenario que duplique los usuarios.
    SELECT COUNT(*) INTO v_ya_existen
    FROM `tb_users`
    WHERE email LIKE CONCAT('sim.p03.t', p_escenario, '.%@example.com');
    IF v_ya_existen > 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Este escenario ya tiene usuarios; revisar antes de repetir';
    END IF;

    START TRANSACTION;
    WHILE v_i <= p_cantidad DO
        IF p_escenario = 1 THEN
            SET v_genero = 'Hombre';
            SET v_pais = 'US';
            SET v_estado = 1;
            SET v_nacimiento = fn_p03_nacimiento(v_i, 19, 65);
        ELSEIF p_escenario = 2 THEN
            SET v_genero = fn_p03_genero(v_i);
            SET v_pais = fn_p03_pais(v_i);
            SET v_estado = 1;
            SET v_nacimiento = fn_p03_nacimiento(v_i, 19, 35);
        ELSE
            SET v_genero = fn_p03_genero(v_i);
            SET v_pais = fn_p03_pais(v_i + 17);
            SET v_estado = fn_p03_activo(v_i, 80);
            SET v_nacimiento = fn_p03_nacimiento(v_i, 18, 65);
        END IF;

        SET v_correo = fn_p03_correo(p_escenario, v_i);
        SET v_nick = CONCAT('sim03_t', p_escenario, '_', LPAD(v_i, 5, '0'));
        SET v_nombre = fn_p03_nombre(v_i, v_genero);
        SET v_apellidos = fn_p03_apellidos(v_i);

        INSERT INTO `tb_users` (`email`, `nick`, `password`, `status`)
        VALUES (v_correo, v_nick, SHA2(CONCAT(UUID(), UUID()), 256), IF(v_estado = 1, b'1', b'0'));

        SET v_id = LAST_INSERT_ID();

        INSERT INTO `tb_people`
            (`user_ID`, `given_names`, `family_names`, `birth_date`, `gender`, `country_code`, `status`)
        VALUES
            (v_id, v_nombre, v_apellidos, v_nacimiento, v_genero, v_pais, IF(v_estado = 1, b'1', b'0'));

        SET v_i = v_i + 1;
    END WHILE;
    COMMIT;

    SELECT p_escenario AS escenario, p_cantidad AS usuarios_insertados,
           'OK: usuarios y personas insertados' AS resultado;
END ;;
DELIMITER ;
